<script setup>
import {ref,watch} from 'vue';import {useRoute,RouterLink} from 'vue-router';import {api} from '../lib/api';import {num} from '../lib/format';import StatTile from '../components/StatTile.vue';import DataChart from '../components/DataChart.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),data=ref(null),error=ref(''),year=ref(''),rubro=ref('');
async function load(){try{data.value=await api.get('/ventas?'+new URLSearchParams({...year.value?{anio:year.value}:{},...rubro.value?{rubro:rubro.value}:{}}))}catch(e){error.value=e.message}}
watch(()=>[route.path,year.value,rubro.value],load,{immediate:true});
</script>
<template><div class="page-heading"><div class="page-heading__titles"><h1 class="page-title display">Ventas</h1><p class="page-description">Facturación neta de Constructora Tocal · Las notas de crédito restan</p></div><div class="page-actions"><RouterLink class="btn" to="/ventas/documentos">Libro de ventas</RouterLink><RouterLink class="btn btn-primary" to="/ventas/importar">Importar XLSX</RouterLink></div></div><p v-if="error" class="notice bad">{{error}}</p><template v-if="data"><div class="page-actions"><select v-model="year"><option value="">Último año</option><option v-for="y in data.years" :key="y" :value="y">{{y}}</option></select><select v-model="rubro"><option value="">Todos los rubros</option><option v-for="[key,label] in data.rubros" :key="key" :value="key">{{label}}</option></select></div><div class="stat-grid cols-4"><StatTile label="Total UF" :value="num(data.sales?.total?.uf,2)" focal/><StatTile label="Total CLP" :value="'$ '+num(data.sales?.total?.clp)"/><StatTile label="Documentos" :value="num(data.sales?.documents)"/><StatTile label="Clientes" :value="num(data.sales?.clients_count)"/></div><PageCard title="Facturación mensual" :description="'Evolución en UF · '+data.year"><DataChart type="monthly" :data="data.monthly" :height="340"/></PageCard><PageCard title="Indicadores comerciales"><div class="tbl-wrap"><table class="tbl"><tbody><tr v-for="(v,k) in data.overview" :key="k"><th>{{String(k).replaceAll('_',' ')}}</th><td>{{typeof v==='object'?JSON.stringify(v):v}}</td></tr></tbody></table></div></PageCard></template></template>
